const updateKbPageHead = `-- name: UpdateKbPageHead :one
UPDATE kb_page SET
    parent_id = $3,
    position = $4,
    slug = $5,
    type = $6,
    title = $7,
    description = $8,
    frontmatter = $9,
    blocks = $10,
    search_text = $11,
    head_revision_id = $12,
    stale_after = $13,
    deleted_at = $14,
    updated_at = now()
WHERE knowledge_base_id = $1 AND id = $2
RETURNING id, workspace_id, knowledge_base_id, parent_id, position, slug, reserved, type, title, description, frontmatter, blocks, search_text, head_revision_id, stale_after, deleted_at, created_at, updated_at
`

type UpdateKbPageHeadParams struct {
	KnowledgeBaseID pgtype.UUID        `json:"knowledge_base_id"`
	ID              pgtype.UUID        `json:"id"`
	ParentID        pgtype.UUID        `json:"parent_id"`
	Position        string             `json:"position"`
	Slug            string             `json:"slug"`
	Type            string             `json:"type"`
	Title           string             `json:"title"`
	Description     string             `json:"description"`
	Frontmatter     []byte             `json:"frontmatter"`
	Blocks          []byte             `json:"blocks"`
	SearchText      string             `json:"search_text"`
	HeadRevisionID  pgtype.UUID        `json:"head_revision_id"`
	StaleAfter      pgtype.Timestamptz `json:"stale_after"`
	DeletedAt       pgtype.Timestamptz `json:"deleted_at"`
}

// Moves the mainline of a page to a new revision.
func (q *Queries) UpdateKbPageHead(ctx context.Context, arg UpdateKbPageHeadParams) (KbPage, error) {
	row := q.db.QueryRow(ctx, updateKbPageHead,
		arg.KnowledgeBaseID,
		arg.ID,
		arg.ParentID,
		arg.Position,
		arg.Slug,
		arg.Type,
		arg.Title,
		arg.Description,
		arg.Frontmatter,
		arg.Blocks,
		arg.SearchText,
		arg.HeadRevisionID,
		arg.StaleAfter,
		arg.DeletedAt,
	)
	var i KbPage
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.KnowledgeBaseID,
		&i.ParentID,
		&i.Position,
		&i.Slug,
		&i.Reserved,
		&i.Type,
		&i.Title,
		&i.Description,
		&i.Frontmatter,
		&i.Blocks,
		&i.SearchText,
		&i.HeadRevisionID,
		&i.StaleAfter,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
